235	    @Override
236	    @Transactional
237	    public void saveOwner(Owner owner) throws DataAccessException {
238	        if (owner.isNew() && owner.getCustomerCode() == null) {
239	            owner.setCustomerCode(generateCustomerCode(owner));
240	        }
241	        if (owner.isNew() && owner.getNamesakeCount() == null) {
242	            owner.setNamesakeCount(countNamesakes(owner));
243	        }
244	        if (owner.isNew() && owner.getHouseholdMemberCount() == null) {
245	            owner.setHouseholdMemberCount(countHouseholdMembers(owner));
246	        }
247	        ownerRepository.save(owner);
248	
249	    }
250	
251	    /**
252	     * Count the members of the new owner's household after this create: the existing owners
253	     * that share the given owner's last name (compared case-insensitively with collapsed
254	     * whitespace) and postcode - the same (last name, postcode) pair from which the household
255	     * identifier is derived - plus the owner being created. Invoked before the new owner is
256	     * persisted.
257	     */
258	    private int countHouseholdMembers(Owner owner) {
259	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
260	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
261	        long existing = ownerRepository.findAll().stream()
262	            .filter(other -> normalizeHouseholdField(other.getLastName()).equals(normalizedLastName)
263	                && postcode.equals(other.getPostcode() == null ? "" : other.getPostcode()))
264	            .count();
265	        return (int) existing + 1;
266	    }
267	
268	    /**
269	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields
270	     * can be compared case-insensitively with collapsed whitespace. A {@code null} value
271	     * normalizes to the empty string.
272	     */
273	    private String normalizeHouseholdField(String value) {
274	        if (value == null) {
275	            return "";
276	        }
277	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
278	    }
279	
280	    /**
281	     * Count the existing owners that share the given owner's first name and last name,
282	     * compared case-insensitively. Invoked before the new owner is persisted, so the
283	     * result is the number of namesakes that existed at the time of creation.
284	     */
285	    private int countNamesakes(Owner owner) {
286	        String firstName = owner.getFirstName();
287	        String lastName = owner.getLastName();
288	        if (firstName == null || lastName == null) {
289	            return 0;
290	        }
291	        return (int) ownerRepository.findAll().stream()
292	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
293	                && lastName.equalsIgnoreCase(existing.getLastName()))
294	            .count();
295	    }
296	
297	    /**
298	     * Build the owner's customer code in the form '<REGION>-<HASH8>' where REGION is the region
299	     * code derived from the owner's postcode (falling back to the city) and HASH8 is the first
300	     * 8 upper-case hex characters of the SHA-256 digest over the owner's normalized telephone
301	     * concatenated with the owner's last name. There is no sequence number: the identity is
302	     * derived entirely from the region and the telephone/last-name hash.
303	     */
304	    private String generateCustomerCode(Owner owner) {
305	        String base = regionFor(owner) + "-" + hash8(owner);
306	        return deduplicateCustomerCode(base);
307	    }
308	
309	    /**
310	     * Ensure the computed customer code is unique across existing owners. When the base code
311	     * collides with an existing owner's {@code customerCode}, append {@code '-<n>'} with the
312	     * smallest {@code n} of 2 or more that makes it unique, and return that de-duplicated code.
313	     */
314	    private String deduplicateCustomerCode(String base) {
315	        Set<String> existing = ownerRepository.findAll().stream()
316	            .map(Owner::getCustomerCode)
317	            .filter(code -> code != null)
318	            .collect(java.util.stream.Collectors.toSet());
319	        if (!existing.contains(base)) {
320	            return base;
321	        }
322	        int n = 2;
323	        while (existing.contains(base + "-" + n)) {
324	            n++;
325	        }
326	        return base + "-" + n;
327	    }
328	
329	    /**
330	     * Derive the owner's region, preferring the postcode over the city. The postcode is looked up
331	     * against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC 3000-3099},
332	     * {@code QLD 4000-4099}); only when the postcode is absent or falls in no known range does the
333	     * derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
334	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). The result is {@code "UNKNOWN"} when neither
335	     * the postcode nor the city resolves to a region.
336	     */
337	    private String regionFor(Owner owner) {
338	        String region = regionFromPostcode(owner.getPostcode());
339	        if (region != null) {
340	            return region;
341	        }
342	        return regionFromCity(owner.getCity());
343	    }
344	
345	    /**
346	     * Look up the canonical region for a postcode by its range ({@code NSW 2000-2099},
347	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code null} when the postcode is
348	     * absent, non-numeric or in no known range.
349	     */
350	    private String regionFromPostcode(String postcode) {
351	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
352	            return null;
353	        }
354	        int value = Integer.parseInt(postcode);
355	        if (value >= 2000 && value <= 2099) {
356	            return "NSW";
357	        }
358	        if (value >= 3000 && value <= 3099) {
359	            return "VIC";
360	        }
361	        if (value >= 4000 && value <= 4099) {
362	            return "QLD";
363	        }
364	        return null;
365	    }
366	
367	    /**
368	     * Look up the canonical region for a city using the fixed city-to-region table, returning
369	     * {@code "UNKNOWN"} when the city is absent or not in the table.
370	     */
371	    private String regionFromCity(String city) {
372	        if (city == null) {
373	            return "UNKNOWN";
374	        }
375	        return switch (city) {
376	            case "Sydney" -> "NSW";
377	            case "Melbourne" -> "VIC";
378	            case "Brisbane" -> "QLD";
379	            default -> "UNKNOWN";
380	        };
381	    }
382	
383	    /**
384	     * Compute the first 8 upper-case hex characters of the SHA-256 digest over the owner's
385	     * normalized telephone concatenated with the owner's last name.
386	     */
387	    private String hash8(Owner owner) {
388	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
389	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
390	        try {
391	            byte[] digest = MessageDigest.getInstance("SHA-256")
392	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
393	            StringBuilder sb = new StringBuilder(8);
394	            for (int i = 0; i < 4; i++) {
395	                sb.append(String.format("%02X", digest[i]));
396	            }
397	            return sb.toString();
398	        }
399	        catch (NoSuchAlgorithmException ex) {
400	            throw new IllegalStateException("SHA-256 not available", ex);
401	        }
402	    }
403	
404	    @Override
405	    @Transactional(readOnly = true)
406	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
407	        return ownerRepository.findByLastName(lastName);
408	    }
409	
410	    @Override
411	    @Transactional(readOnly = true)
412	    public Collection<Visit> findVisitsByPetId(int petId) {
413	        return visitRepository.findByPetId(petId);
414	    }
415	
416	    @Override
417	    @Transactional(readOnly = true)
418	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
419	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
420	    }
421	
422	    private <T> T findEntityById(Supplier<T> supplier) {
423	        try {
424	            return supplier.get();
425	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
426	            // Just ignore not found exceptions for Jdbc/Jpa realization
427	            return null;
428	        }
429	    }
430	
431	}
