66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
73	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
74	     * address shape rather than full RFC 5322 conformance.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Disposable email domains that are not accepted for an owner's email. An email whose domain
81	     * (the part after the {@code @}, compared case-insensitively) is on this blocklist is rejected.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
84	        "mailinator.com",
85	        "tempmail.com",
86	        "guerrillamail.com");
87	
88	    /**
89	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
90	     * owner's id, customer code and registration date so the side-effect can be observed
91	     * independently of the HTTP response.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Common street-type abbreviations expanded during address normalization. Keys and values are
97	     * upper-cased so the mapping is applied after the address has been upper-cased.
98	     */
99	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
100	        "ST", "STREET",
101	        "RD", "ROAD",
102	        "AVE", "AVENUE");
103	
104	    /**
105	     * Maximum number of owners permitted in a single city. Once a city already contains this many
106	     * owners, creating another owner in that city is rejected as a conflict.
107	     */
108	    private static final int CITY_CAPACITY = 50;
109	
110	    /**
111	     * Fixed list of public holidays. A registration date that, after the weekend adjustment, lands on
112	     * one of these dates is rolled forward to the next non-holiday business day.
113	     */
114	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
115	        LocalDate.of(2026, 1, 1),
116	        LocalDate.of(2026, 1, 26),
117	        LocalDate.of(2026, 4, 25),
118	        LocalDate.of(2026, 12, 25),
119	        LocalDate.of(2026, 12, 28));
120	
121	    /**
122	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
123	     * already share the current registration date, creating another owner today is rejected.
124	     */
125	    private static final int DAILY_OWNER_LIMIT = 100;
126	
127	    /**
128	     * Number of owner registrations on a single business day above which a newly created owner is
129	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
130	     * registration date, the surge is signalled in the response; the create itself still succeeds.
131	     */
132	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
133	
134	    /**
135	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
136	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
137	     * a city that is not listed has no known region and accepts any 4-digit postcode.
138	     */
139	    private static final Map<String, String> CITY_REGIONS = Map.of(
140	        "Sydney", "NSW",
141	        "Melbourne", "VIC",
142	        "Brisbane", "QLD");
143	
144	    /**
145	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
146	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
147	     */
148	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
149	        "NSW", new int[] {2000, 2099},
150	        "VIC", new int[] {3000, 3099},
151	        "QLD", new int[] {4000, 4099});
152	
153	    /**
154	     * Request header carrying the client-supplied idempotency key. When a create request repeats with
155	     * a key that has already produced an owner, the original owner is returned with {@code 200 OK}
156	     * instead of creating a duplicate.
157	     */
158	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
159	
160	    /**
161	     * Maps a previously seen {@code Idempotency-Key} to the id of the owner it created, so a repeated
162	     * create with the same key resolves to the originally created owner rather than creating a
163	     * duplicate. Kept in memory for the lifetime of this singleton controller and safe for concurrent
164	     * access across requests.
165	     */
166	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
167	
168	    private final ClinicService clinicService;
169	
170	    private final OwnerMapper ownerMapper;
171	
172	    private final PetMapper petMapper;
173	
174	    private final VisitMapper visitMapper;
175	
176	    private final jakarta.servlet.http.HttpServletRequest request;
