212	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
213	    }
214	
215	    /**
216	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
217	     * upper-cases the value, and expands common street-type abbreviations word-by-word
218	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
219	     * normalizes to the empty string. The normalized value is what the application stores, returns
220	     * and compares for household detection.
221	     *
222	     * @param address the raw address value from the request, may be {@code null}
223	     * @return the normalized address, or the empty string when none was supplied
224	     */
225	    private String normalizeAddress(String address) {
226	        if (address == null) {
227	            return "";
228	        }
229	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
230	        if (collapsed.isEmpty()) {
231	            return "";
232	        }
233	        String[] tokens = collapsed.split(" ");
234	        StringBuilder normalized = new StringBuilder();
235	        for (int i = 0; i < tokens.length; i++) {
236	            if (i > 0) {
237	                normalized.append(' ');
238	            }
239	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
240	        }
241	        return normalized.toString();
242	    }
243	
244	    /**
245	     * Applies address normalization to whichever address form the request supplied, preferring the
246	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
247	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
248	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
249	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
250	     * appended - so everything downstream that reads {@code address} sees the structured value. When
251	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
252	     * earlier minimal owners backward-compatible.
253	     *
254	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
255	     */
256	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
257	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
258	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
259	            ownerFieldsDto.setAddressLine1(line1);
260	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
261	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
262	                ownerFieldsDto.setAddressLine2(line2);
263	                ownerFieldsDto.setAddress(line1 + " " + line2);
264	            } else {
265	                ownerFieldsDto.setAddressLine2(null);
266	                ownerFieldsDto.setAddress(line1);
267	            }
268	        } else {
269	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
270	        }
271	    }
272	
273	    /**
274	     * Rejects an owner payload that is missing or blank in any required field. The response body's
275	     * {@code errors} array lists the name of each offending field.
276	     *
277	     * @param ownerFieldsDto the owner payload to validate
278	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
279	     */
280	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
281	        List<String> missingFields = new ArrayList<>();
282	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
283	            missingFields.add("firstName");
284	        }
285	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
286	            missingFields.add("lastName");
287	        }
288	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
289	            missingFields.add("address");
290	        }
291	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
292	            missingFields.add("city");
293	        }
294	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
295	            missingFields.add("telephone");
296	        }
297	        if (!missingFields.isEmpty()) {
298	            throw new RequiredFieldsMissingException(missingFields);
299	        }
300	    }
301	
302	    /**
303	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
304	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
305	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
306	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
307	     * region accepts any 4-digit postcode.
308	     *
309	     * @param postcode the raw postcode value from the request, may be {@code null}
310	     * @param city the owner's city, used to look up the region whose range constrains the postcode
311	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
312	     */
313	    private void validatePostcode(String postcode, String city) {
314	        if (postcode == null) {
315	            return;
316	        }
317	        if (!postcode.matches("[0-9]{4}")) {
318	            throw new InvalidFieldsException(List.of("postcode"));
319	        }
320	        String region = CITY_REGIONS.get(city);
321	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
322	        if (range != null) {
323	            int value = Integer.parseInt(postcode);
324	            if (value < range[0] || value > range[1]) {
325	                throw new InvalidFieldsException(List.of("postcode"));
326	            }
327	        }
328	    }
329	
330	    /**
331	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
332	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
333	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
334	     * followed by 8 to 15 digits.
335	     *
336	     * @param telephone the raw telephone value from the request
337	     * @return the E.164 telephone (e.g. {@code +61412345678})
338	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
339	     */
340	    private String normalizeTelephone(String telephone) {
341	        if (telephone == null) {
342	            throw new InvalidFieldsException(List.of("telephone"));
343	        }
344	        String trimmed = telephone.trim();
345	        boolean international = trimmed.startsWith("+");
346	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
347	        String digits;
348	        if (international) {
349	            digits = cleaned.substring(1);
350	        } else {
351	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
352	            digits = "61" + national;
353	        }
354	        if (!digits.matches("[0-9]{8,15}")) {
355	            throw new InvalidFieldsException(List.of("telephone"));
356	        }
357	        requireValidNationalLength(digits);
358	        return "+" + digits;
359	    }
360	
361	    /**
362	     * Country codes with a fixed national-number length, checked longest-prefix first so that
363	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
364	     * digits; the North American Numbering Plan ('1') requires 10.
365	     */
366	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
367	
368	    /**
369	     * Validates that the national number (the E.164 digits after the country code) has the length
370	     * required for its country. Country codes without a known fixed length are left to the general
371	     * E.164 length check.
372	     *
373	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
374	     * @throws InvalidFieldsException if the national number is the wrong length for its country
375	     */
376	    private void requireValidNationalLength(String digits) {
377	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
378	            .filter(entry -> digits.startsWith(entry.getKey()))
379	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
380	            .ifPresent(entry -> {
381	                int nationalLength = digits.length() - entry.getKey().length();
382	                if (nationalLength != entry.getValue()) {
383	                    throw new InvalidFieldsException(List.of("telephone"));
384	                }
385	            });
386	    }
387	
388	    /**
389	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
390	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
391	     * be a syntactically valid address; the accepted value is returned lower-cased.
392	     *
393	     * @param email the raw email value from the request, may be {@code null}
394	     * @return the lower-cased email, or {@code null} when none was supplied
395	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
396	     */
397	    private String normalizeEmail(String email) {
398	        if (email == null || email.isBlank()) {
399	            return null;
400	        }
401	        String trimmed = email.trim();
402	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
403	            throw new InvalidFieldsException(List.of("email"));
404	        }
405	        String normalized = trimmed.toLowerCase(Locale.ROOT);
406	        String domain = normalized.substring(normalized.indexOf('@') + 1);
407	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
408	            throw new InvalidFieldsException(List.of("email"));
409	        }
410	        return normalized;
411	    }
412	
413	    /**
414	     * Rejects an owner that collides with an existing owner on their derived identity key. All
415	     * duplicate detection is consolidated into this single key
416	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
417	     * the former separate telephone, email and household checks.
418	     *
419	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
420	     * share the same normalized telephone. Because the telephone is the leading, always-present part
421	     * of the key, two members of the same household with <em>different</em> telephones have different
422	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
423	     * scenario in the acceptance suite exercises - is rejected.
424	     *
425	     * @param owner the owner being created, with its normalized telephone and email already applied
426	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
427	     */
428	    /**
429	     * Tests whether an existing owner is not soft-deleted, so that duplicate and identity detection
430	     * can ignore owners flagged {@code deleted}. An owner whose {@code deleted} flag is {@code null}
431	     * or {@code false} is considered active; only an explicit {@code true} excludes it.
432	     *
433	     * @param owner an existing owner from the data store
434	     * @return {@code true} when the owner is not flagged deleted, otherwise {@code false}
435	     */
436	    private static boolean isNotDeleted(Owner owner) {
437	        return !Boolean.TRUE.equals(owner.getDeleted());
438	    }
439	
440	    private void requireUniqueIdentity(Owner owner) {
441	        String telephone = owner.getTelephone();
442	        boolean taken = this.clinicService.findAllOwners().stream()
443	            .filter(OwnerRestControllerV1::isNotDeleted)
444	            .map(Owner::getTelephone)
445	            .anyMatch(existing -> existing != null && existing.equals(telephone));
446	        if (taken) {
447	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
448	        }
449	    }
450	
451	    /**
452	     * Rejects an owner that would join an existing owner's household without opting in. The household
453	     * is keyed by the owner's computed {@link OwnerMapper#householdId(Owner) household id} - the first
454	     * 12 hex characters of SHA-256 over the normalized last name and postcode - so two owners sharing
455	     * a last name and postcode belong to the same household even with different addresses or
456	     * telephones. A collision is only raised against an existing household member that also shares the
457	     * new owner's email (compared case-insensitively, a missing email matching another missing email):
458	     * a member who supplies a distinct email is a distinguishable person and is admitted without an
459	     * opt-in. Only owners with a postcode participate: an owner without a postcode has no well-defined
460	     * household and is never blocked here. The check is bypassed by the caller when the request sets
461	     * {@code sharesHousehold}, so a declared household member is created rather than rejected.
462	     *
463	     * @param owner the owner being created, with its normalized fields already applied
464	     * @throws DuplicateOwnerHouseholdException if an existing owner shares the household id and email
465	     */
466	    private void requireNoHouseholdDuplicate(Owner owner) {
467	        if (owner.getPostcode() == null) {
468	            return;
469	        }
470	        String householdId = ownerMapper.householdId(owner);
471	        boolean taken = this.clinicService.findAllOwners().stream()
472	            .filter(OwnerRestControllerV1::isNotDeleted)
473	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
474	            .anyMatch(existing -> sameEmail(owner, existing));
475	        if (taken) {
476	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getPostcode());
477	        }
478	    }
479	
480	    /**
481	     * Tests whether two owners carry the same email for household-duplicate detection. Emails are
482	     * already normalized (trimmed, lower-cased) when an owner is created; a {@code null} or blank
483	     * email is treated as the empty string, so two owners that both omit an email compare equal.
484	     *
485	     * @param owner the owner being created
486	     * @param existing an existing owner sharing the household id
487	     * @return {@code true} when both owners carry the same email
488	     */
489	    private static boolean sameEmail(Owner owner, Owner existing) {
490	        return normalizeEmailKey(owner.getEmail()).equals(normalizeEmailKey(existing.getEmail()));
491	    }
492	
493	    private static String normalizeEmailKey(String email) {
494	        return email == null ? "" : email.trim().toLowerCase(Locale.ROOT);
495	    }
496	
497	    /**
498	     * Computes the membership level ceiling for the owner being created: one above the current
499	     * maximum membership level among the existing members of the owner's household (those sharing its
500	     * computed {@link OwnerMapper#householdId(Owner) household id}, ignoring soft-deleted owners). Each
501	     * existing member's level is evaluated for the household size that now includes the joining owner,
502	     * so the ceiling reflects the household's up-to-date standing. Returns {@code null} when the
503	     * household has no existing member, in which case no cap applies. Invoked before the new owner is
504	     * persisted, so it never counts the owner itself.
505	     *
506	     * @param owner the owner being created, with its normalized fields already applied
507	     * @return the capped maximum membership level, or {@code null} when no existing household member
508	     */
509	    private Integer householdMembershipLevelCap(Owner owner) {
510	        String householdId = ownerMapper.householdId(owner);
511	        List<Owner> members = this.clinicService.findAllOwners().stream()
512	            .filter(OwnerRestControllerV1::isNotDeleted)
513	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
514	            .toList();
515	        if (members.isEmpty()) {
516	            return null;
517	        }
518	        int householdSize = members.size() + 1;
519	        int maxLevel = members.stream()
520	            .mapToInt(existing -> ownerMapper.householdMemberLevel(existing, householdSize))
521	            .max()
522	            .getAsInt();
523	        return maxLevel + 1;
524	    }
525	
526	    /**
527	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
528	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
529	     * normalizes to the empty string.
530	     *
531	     * @param value the raw field value, may be {@code null}
532	     * @return the trimmed, whitespace-collapsed, lower-cased form
533	     */
534	    private String normalizeHousehold(String value) {
535	        if (value == null) {
536	            return "";
537	        }
538	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
539	    }
540	
541	    /**
542	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
543	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
544	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
545	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
546	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
547	     * returned so the result is deterministic.
548	     *
549	     * @param owner the owner being created, with its normalized telephone already applied
550	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
551	     */
552	    private Owner findPossibleDuplicate(Owner owner) {
553	        String lastName = owner.getLastName();
554	        String postcode = owner.getPostcode();
555	        if (lastName == null || postcode == null) {
556	            return null;
557	        }
558	        String telephone = owner.getTelephone();
559	        return this.clinicService.findAllOwners().stream()
560	            .filter(OwnerRestControllerV1::isNotDeleted)
561	            .filter(existing -> postcode.equals(existing.getPostcode()))
562	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
563	            .filter(existing -> existing.getTelephone() == null
564	                || !existing.getTelephone().equals(telephone))
565	            .min(Comparator.comparingInt(Owner::getId))
566	            .orElse(null);
567	    }
568	
569	    /**
570	     * Rejects an owner whose city already contains the maximum permitted number of owners
571	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
572	     * the same normalization used for the other owner household fields.
573	     *
574	     * @param city the city of the owner being created
575	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
576	     */
577	    private void requireCityHasCapacity(String city) {
578	        String normalizedCity = normalizeHousehold(city);
579	        long count = this.clinicService.findAllOwners().stream()
580	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
581	            .count();
582	        if (count >= CITY_CAPACITY) {
583	            throw new CityAtCapacityException(city);
584	        }
585	    }
586	
587	    /**
588	     * Rejects creating an owner once the given business day has already reached the maximum
589	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
590	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
591	     * registration date.
592	     *
593	     * @param registrationDate the business-day-adjusted registration date of the owner being created
594	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
595	     *     registered on that business day
596	     */
597	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
598	        long count = this.clinicService.findAllOwners().stream()
599	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
600	            .count();
601	        if (count >= DAILY_OWNER_LIMIT) {
602	            throw new DailyOwnerLimitException(registrationDate);
603	        }
604	    }
605	
606	    /**
607	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
608	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
609	     * been registered on that date. Evaluated before the new owner is persisted, so the count
610	     * reflects the owners that existed at the time of creation.
611	     *
612	     * @param registrationDate the business-day-adjusted registration date of the owner being created
613	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
614	     *     that registration date, otherwise {@code false}
615	     */
616	    private boolean isBulkSignup(LocalDate registrationDate) {
617	        long count = this.clinicService.findAllOwners().stream()
618	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
619	            .count();
620	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
621	    }
622	
623	    /**
624	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
625	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
626	     * date in the future is invalid.
627	     *
628	     * @param registrationDate the registration date supplied on the request, may be {@code null}
629	     * @throws InvalidFieldsException if the supplied date is later than today's server date
630	     */
631	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
632	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
633	            throw new InvalidFieldsException(List.of("registrationDate"));
634	        }
635	    }
636	
637	    /**
638	     * Rolls a registration date forward onto a business day: any Saturday, Sunday or listed public
639	     * holiday is advanced day by day until the first weekday that is not a public holiday, while a
640	     * plain weekday is returned unchanged.
641	     *
642	     * @param date the effective registration date (supplied or defaulted to the server date)
643	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
644	     */
645	    private LocalDate toBusinessDay(LocalDate date) {
646	        LocalDate result = date;
647	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
648	            result = result.plusDays(1);
649	        }
650	        return result;
651	    }
652	
653	    private boolean isWeekend(LocalDate date) {
654	        return switch (date.getDayOfWeek()) {
655	            case SATURDAY, SUNDAY -> true;
656	            default -> false;
657	        };
658	    }
659	
660	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
661	    @Override
662	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
663	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
664	        if (StringUtils.hasText(idempotencyKey)) {
665	            Integer existingId = idempotentCreates.get(idempotencyKey);
666	            if (existingId != null) {
667	                Owner existing = this.clinicService.findOwnerById(existingId);
668	                if (existing != null) {
669	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
670	                }
671	            }
672	        }
673	        applyAddressFields(ownerFieldsDto);
674	        validateRequiredFields(ownerFieldsDto);
675	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
676	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
677	        requireCityHasCapacity(ownerFieldsDto.getCity());
678	        String email = normalizeEmail(ownerFieldsDto.getEmail());
679	        HttpHeaders headers = new HttpHeaders();
680	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
681	        owner.setTelephone(telephone);
682	        owner.setEmail(email);
683	        owner.setDeleted(false);
684	        requireUniqueIdentity(owner);
685	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
686	        if (!sharesHousehold) {
687	            requireNoHouseholdDuplicate(owner);
688	        }
689	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
690	        LocalDate effectiveDate = owner.getRegistrationDate() != null
691	            ? owner.getRegistrationDate() : LocalDate.now();
692	        LocalDate registrationDate = toBusinessDay(effectiveDate);
693	        owner.setRegistrationDate(registrationDate);
694	        requireDailyLimitNotReached(registrationDate);
695	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
696	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
697	        owner.setPossibleDuplicate(possibleDuplicate != null);
698	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
699	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner));
700	        this.clinicService.saveOwner(owner);
701	        if (StringUtils.hasText(idempotencyKey)) {
702	            idempotentCreates.put(idempotencyKey, owner.getId());
703	        }
704	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
705	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
706	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
707	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
708	        headers.setLocation(UriComponentsBuilder.newInstance()
709	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
710	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
716	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
717	        if (currentOwner == null) {
718	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
719	        }
720	        currentOwner.setAddress(ownerFieldsDto.getAddress());
721	        currentOwner.setCity(ownerFieldsDto.getCity());
722	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
723	        currentOwner.setLastName(ownerFieldsDto.getLastName());
724	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
725	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
726	        this.clinicService.saveOwner(currentOwner);
727	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
728	    }
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Transactional
732	    @Override
733	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
734	        Owner owner = this.clinicService.findOwnerById(ownerId);
735	        if (owner == null) {
736	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
737	        }
738	        owner.setDeleted(true);
739	        this.clinicService.saveOwner(owner);
740	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
741	    }
742	
743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Override
745	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
746	        Owner owner = this.clinicService.findOwnerById(ownerId);
747	        if (owner == null) {
748	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
749	        }
750	        HttpHeaders headers = new HttpHeaders();
751	        Pet pet = petMapper.toPet(petFieldsDto);
752	        owner.setId(ownerId);
753	        pet.setOwner(owner);
754	        pet.getType().setName(null);
755	        this.clinicService.savePet(pet);
756	        PetDto petDto = petMapper.toPetDto(pet);
757	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
758	            .buildAndExpand(pet.getId()).toUri());
759	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
760	    }
761	
762	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
763	    @Override
764	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
765	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
766	        if (currentOwner != null) {
767	            Pet currentPet = this.clinicService.findPetById(petId);
768	            if (currentPet != null) {
769	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
770	                currentPet.setName(petFieldsDto.getName());
771	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
772	                this.clinicService.savePet(currentPet);
773	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
774	            }
775	        }
776	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
777	    }
778	
779	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
780	    @Override
781	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
782	        HttpHeaders headers = new HttpHeaders();
783	        Visit visit = visitMapper.toVisit(visitFieldsDto);
784	        Pet pet = new Pet();
785	        pet.setId(petId);
786	        visit.setPet(pet);
787	        this.clinicService.saveVisit(visit);
788	        VisitDto visitDto = visitMapper.toVisitDto(visit);
789	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
790	            .buildAndExpand(visit.getId()).toUri());
791	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
792	    }
793	
794	
795	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
796	    @Override
797	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
798	        Owner owner = this.clinicService.findOwnerById(ownerId);
799	        if (owner != null) {
800	            Pet pet = owner.getPet(petId);
801	            if (pet != null) {
802	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
803	            }
804	        }
805	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
806	    }
807	}
