46	    /**
47	     * Derives a link to the owner's own resource, formatted {@code /api/owners/<id>} where
48	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet, so the
49	     * field is omitted from the response.
50	     *
51	     * @param owner the owner to derive the self link for
52	     * @return the {@code /api/owners/<id>} self link, or {@code null} when the owner has no id
53	     */
54	    default String selfLink(Owner owner) {
55	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
56	    }
57	
58	    /**
59	     * Derives an owner's salutation from its optional title and last name: {@code "<title> <lastName>"}
60	     * when a non-blank title is present, or just the last name when no title was supplied.
61	     *
62	     * @param owner the owner to derive the salutation for
63	     * @return the composed salutation
64	     */
65	    default String salutation(Owner owner) {
66	        String title = owner.getTitle();
67	        String lastName = owner.getLastName();
68	        if (title == null || title.isBlank()) {
69	            return lastName;
70	        }
71	        return title + " " + lastName;
72	    }
73	
74	    /**
75	     * Derives an owner's age band from its birth date, computed as the owner's age on its
76	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
77	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
78	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
79	     * response.
80	     *
81	     * @param owner the owner to derive the age band for
82	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
83	     *     is held
84	     */
85	    default String ageBand(Owner owner) {
86	        java.time.LocalDate birthDate = owner.getBirthDate();
87	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
88	        if (birthDate == null || registrationDate == null) {
89	            return null;
90	        }
91	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
92	        if (age < 18) {
93	            return "MINOR";
94	        }
95	        return age < 65 ? "ADULT" : "SENIOR";
96	    }
97	
98	    /**
99	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
100	     * email, otherwise {@code "PHONE"}.
101	     *
102	     * @param owner the owner to derive the contact preference for
103	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
104	     */
105	    default String contactPreference(Owner owner) {
106	        String email = owner.getEmail();
107	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
108	    }
109	
110	    /**
111	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
112	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
113	     * normalizing telephones into E.164 form.
114	     */
115	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
116	
117	    /**
118	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
119	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
120	     * The country code is taken as the longest recognized prefix (see
121	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
122	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
123	     * is returned unchanged.
124	     *
125	     * @param owner the owner to format the telephone display for
126	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
127	     *     digit string
128	     */
129	    default String telephoneDisplay(Owner owner) {
130	        String telephone = owner.getTelephone();
131	        if (telephone == null || !telephone.startsWith("+")) {
132	            return telephone;
133	        }
134	        String digits = telephone.substring(1);
135	        if (!digits.matches("[0-9]+")) {
136	            return telephone;
137	        }
138	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
139	            .filter(digits::startsWith)
140	            .max(java.util.Comparator.comparingInt(String::length))
141	            .orElseGet(() -> digits.substring(0, 1));
142	        String national = digits.substring(countryCode.length());
143	        StringBuilder sb = new StringBuilder("+").append(countryCode);
144	        for (int i = 0; i < national.length(); i += 3) {
145	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
146	        }
147	        return sb.toString();
148	    }
149	
150	    /**
151	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
152	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
153	     * the customer code's region is itself derived from the postcode (falling back to the city), the
154	     * locality now moves with the identity rather than being computed independently. The result is
155	     * {@code "UNKNOWN"} when no customer code is present.
156	     *
157	     * @param owner the owner to derive the locality for
158	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
159	     */
160	    default String locality(Owner owner) {
161	        String code = owner.getCustomerCode();
162	        if (code == null || code.isEmpty()) {
163	            return "UNKNOWN";
164	        }
165	        int dash = code.indexOf('-');
166	        return dash < 0 ? code : code.substring(0, dash);
167	    }
168	
169	    /**
170	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
171	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
172	     */
173	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
174	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
175	
176	    /**
177	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
178	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
179	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
180	     * the field is omitted from the response.
181	     *
182	     * @param owner the owner to derive the timezone for
183	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
184	     */
185	    default String timezone(Owner owner) {
186	        return REGION_TIMEZONES.get(locality(owner));
187	    }
188	
189	    /**
190	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
191	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
192	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
193	     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
194	     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
195	     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
196	     * points.
197	     *
198	     * @param owner the owner to derive the membership points for
199	     * @return the membership points, {@code 0} or more
200	     */
201	    default Integer membershipPoints(Owner owner) {
202	        return membershipPoints(owner, owner.getHouseholdMemberCount());
203	    }
204	
205	    /**
206	     * Derives an owner's membership points as {@link #membershipPoints(Owner)}, but scoring the
207	     * household bonus against the supplied household member count rather than the owner's stored one.
208	     * Used to evaluate an existing household member's current standing against the household size that
209	     * includes a newly joining owner.
210	     *
211	     * @param owner the owner to derive the membership points for
212	     * @param householdMemberCount the household member count to score the household bonus against
213	     * @return the membership points, {@code 0} or more
214	     */
215	    private int membershipPoints(Owner owner, Integer householdMemberCount) {
216	        int points = 0;
217	        String email = owner.getEmail();
218	        if (email != null && !email.isBlank()) {
219	            points += 2;
220	        }
221	        Integer namesakeCount = owner.getNamesakeCount();
222	        if (namesakeCount != null && namesakeCount == 0) {
223	            points += 1;
224	        }
225	        if (householdMemberCount != null && householdMemberCount >= 3) {
226	            points += 2;
227	        }
228	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
229	        long tenureFiscalYears = registrationDate == null ? 0
230	            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
231	        if (tenureFiscalYears > 1) {
232	            points += 3;
233	        }
234	        return points;
235	    }
236	
237	    /**
238	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
239	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
240	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more. The points-derived
241	     * level is then capped by the owner's {@link Owner#getMembershipLevelCap() membership level cap}
242	     * when one was recorded at creation - a new owner's level can never exceed one above the highest
243	     * level among the household members that already existed. When no cap was recorded (the owner had
244	     * no existing household member) the points-derived level is returned unchanged.
245	     *
246	     * @param owner the owner to derive the membership level for
247	     * @return the membership level, between {@code 1} and {@code 4}
248	     */
249	    default Integer membershipLevel(Owner owner) {
250	        return cappedLevel(owner, levelForPoints(membershipPoints(owner)));
251	    }
252	
253	    /**
254	     * Derives an existing household member's current membership level as it would stand in a household
255	     * of the supplied size, so a newly joining owner's level ceiling can be measured against the
256	     * up-to-date standing of the members it joins. The member's own {@link Owner#getMembershipLevelCap()
257	     * cap} still applies.
258	     *
259	     * @param owner the existing household member to evaluate
260	     * @param householdMemberCount the household member count that includes the joining owner
261	     * @return the member's capped membership level for that household size, between {@code 1} and {@code 4}
262	     */
263	    default Integer householdMemberLevel(Owner owner, int householdMemberCount) {
264	        return cappedLevel(owner, levelForPoints(membershipPoints(owner, householdMemberCount)));
265	    }
266	
267	    /**
268	     * Applies an owner's {@link Owner#getMembershipLevelCap() membership level cap} to a points-derived
269	     * level: the level is returned unchanged when no cap was recorded, otherwise it is clamped to the
270	     * cap.
271	     *
272	     * @param owner the owner whose cap is applied
273	     * @param level the uncapped points-derived level
274	     * @return the capped level
275	     */
276	    private Integer cappedLevel(Owner owner, int level) {
277	        Integer cap = owner.getMembershipLevelCap();
278	        if (cap != null && level > cap) {
279	            return cap;
280	        }
281	        return level;
282	    }
283	
284	    /**
285	     * Maps membership points to a numeric level: level {@code 1} for {@code 0}-{@code 1} points,
286	     * {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}, and {@code 4} for
287	     * {@code 6} or more.
288	     *
289	     * @param points the membership points
290	     * @return the points-based membership level, between {@code 1} and {@code 4}
291	     */
292	    private Integer levelForPoints(int points) {
293	        if (points <= 1) {
294	            return 1;
295	        }
296	        if (points <= 3) {
297	            return 2;
298	        }
299	        if (points <= 5) {
300	            return 3;
301	        }
302	        return 4;
303	    }
304	
305	    /**
306	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
307	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
308	     * two digits (zero-padded) of the owner's {@link #fiscalYear(Owner) fiscal year} - so the year
309	     * segment matches the returned {@code fiscalYear} (e.g. {@code NSW-1A2B3C4D-M27}).
310	     *
311	     * @param owner the owner to derive the membership number for
312	     * @return the formatted membership number
313	     */
314	    default String membershipNumber(Owner owner) {
315	        String yy = String.format("%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
316	        return owner.getCustomerCode() + "-M" + yy;
317	    }
318	
319	    /**
320	     * Derives an owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
321	     * digits (zero-padded) of the fiscal year that the owner's business-day-adjusted registration
322	     * date falls in. The fiscal year starts on 1 July and is labelled by the calendar year in which
323	     * it ends, so a registration date on or after 1 July belongs to the next year's fiscal year
324	     * (e.g. {@code 2026-08-11 -> FY27}, {@code 2026-01-05 -> FY26}).
325	     *
326	     * @param owner the owner to derive the fiscal year for
327	     * @return the formatted fiscal year
328	     */
329	    default String fiscalYear(Owner owner) {
330	        return String.format("FY%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
331	    }
332	
333	    /**
334	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
335	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
336	     * December belongs to the following calendar year's fiscal year and a date in January through
337	     * June belongs to its own calendar year's fiscal year.
338	     *
339	     * @param date the date to compute the fiscal year for
340	     * @return the fiscal year as a four-digit calendar year
341	     */
342	    private int fiscalYearValue(java.time.LocalDate date) {
343	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
344	    }
345	
346	    /**
347	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
348	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
349	     * are ignored.
350	     *
351	     * @param owner the owner to derive the check digit for
352	     * @return the Luhn check digit, between {@code 0} and {@code 9}
353	     */
354	    default Integer checkDigit(Owner owner) {
355	        String code = owner.getCustomerCode();
356	        int sum = 0;
357	        boolean dbl = true;
358	        for (int i = code.length() - 1; i >= 0; i--) {
359	            char c = code.charAt(i);
360	            if (c < '0' || c > '9') {
361	                continue;
362	            }
363	            int d = c - '0';
364	            if (dbl) {
365	                d *= 2;
366	                if (d > 9) {
367	                    d -= 9;
368	                }
369	            }
370	            sum += d;
371	            dbl = !dbl;
372	        }
373	        return (10 - (sum % 10)) % 10;
374	    }
375	
376	    /**
377	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
378	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
379	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
380	     * string. Because it is derived deterministically from the last name and postcode, every owner
381	     * that shares those two fields receives the same value - including owners created via the
382	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
383	     *
384	     * @param owner the owner to derive the household identifier for
385	     * @return the 12 upper-case hex character household identifier, never blank
386	     */
387	    default String householdId(Owner owner) {
388	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
389	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
390	        try {
391	            byte[] digest = MessageDigest.getInstance("SHA-256")
392	                .digest(key.getBytes(StandardCharsets.UTF_8));
393	            StringBuilder sb = new StringBuilder(12);
394	            for (int i = 0; i < 6; i++) {
395	                sb.append(String.format("%02X", digest[i]));
396	            }
397	            return sb.toString();
398	        }
399	        catch (NoSuchAlgorithmException ex) {
400	            throw new IllegalStateException("SHA-256 not available", ex);
401	        }
402	    }
403	
404	    /**
405	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
406	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
407	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
408	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
409	     * whole identity keys are equal; because the telephone is part of the key, household members with
410	     * different telephones have different keys.
411	     *
412	     * @param owner the owner to derive the identity key for
413	     * @return the {@code telephone|email|householdId} identity key
414	     */
415	    default String identityKey(Owner owner) {
416	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
417	        String email = owner.getEmail() == null ? "" : owner.getEmail();
418	        return telephone + '|' + email + '|' + householdId(owner);
419	    }
420	
421	    /**
422	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
423	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
424	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
425	     *
426	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
427	     * conversion and apply it to unrelated String properties (last name, address, ...).
428	     */
429	    private String normalizeHouseholdField(String value) {
430	        if (value == null) {
431	            return "";
432	        }
433	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
434	    }
435	
436	    Owner toOwner(OwnerDto ownerDto);
437	
438	    @Mapping(target = "id", ignore = true)
439	    @Mapping(target = "pets", ignore = true)
440	    Owner toOwner(OwnerFieldsDto ownerDto);
441	
442	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
443	
444	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
445	
446	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
447	        OwnerPageDto ownerPageDto = new OwnerPageDto();
448	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
449	        ownerPageDto.setPage(ownerPage.getNumber());
450	        ownerPageDto.setSize(ownerPage.getSize());
451	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
452	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
453	        return ownerPageDto;
454	    }
455	}
