1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Tag;
4	import org.junit.jupiter.api.Test;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
6	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
7	import tools.jackson.databind.node.ObjectNode;
8	
9	/** household-duplicate: the soundex identity key includes the telephone, so
10	 * two owners with the same lastName and postcode but DIFFERENT telephones are no longer a hard
11	 * household duplicate. They are created as a soft match (possibleDuplicate true), not rejected with
12	 * 409 -- the separate household-duplicate block no longer applies once duplicate detection is the
13	 * single identity key. */
14	@Tag("cp10")
15	class Cp10Tests extends AcceptanceBase {
16	
17		@Test
18		void coreSameLastNameAndPostcodeNoLongerHardDuplicate() throws Exception {
19			String lastName = uniqueLastName();
20			ObjectNode a = ownerNode();
21			a.put("lastName", lastName);
22			a.put("postcode", "2000");
23			createOwnerOk(a);
24			ObjectNode b = ownerNode(); // same lastName + postcode, unique telephone -> soft match, not 409
25			b.put("lastName", lastName);
26			b.put("postcode", "2000");
27			int id = createOwnerOk(b);
28			getOwner(id).andExpect(status().isOk())
